const el=id=>document.getElementById(id),renderer=new Screen(el('screen'));
const workerURL=URL.createObjectURL(new Blob([WORKER_SOURCE],{type:'text/javascript'})),w=new Worker(workerURL);
let pkg=GAMES.dino,gen=0,ready=false,busy=false,paused=false,keys=0,touch=0,next=0,context=null,sound=false,schedule=0,last=-1,sources=new Set();
function silence(){for(const s of sources){try{s.stop();}catch{}}sources.clear();schedule=0;}
function load(){ready=false;busy=false;paused=false;keys=touch=0;last=-1;gen++;silence();w.postMessage({type:'load',generation:gen,package:pkg});el('pause').textContent='Pausar';}
w.onmessage=({data:d})=>{if(d.generation!==undefined&&d.generation!==gen)return;if(d.type==='ready'){ready=true;busy=false;last=-1;}else if(d.type==='frame'){busy=false;renderer.draw(d.pixels);el('status').textContent=(d.stats.ms/1000).toFixed(2)+' s virtuais · '+d.stats.frames+' quadros · '+renderer.mode;
 if(sound&&!paused&&context?.state==='running'&&d.audio.length){if(schedule>context.currentTime+.35)silence();const b=context.createBuffer(1,d.audio.length,48000);b.copyToChannel(d.audio,0);const s=context.createBufferSource();s.buffer=b;s.connect(context.destination);schedule=Math.max(schedule,context.currentTime+.035);s.start(schedule);schedule+=b.duration;sources.add(s);s.onended=()=>sources.delete(s);}
 }else if(d.type==='error'){ready=false;busy=false;el('status').textContent=d.message;silence();}else if(d.type==='idle')busy=false;};
function tick(t){let mask=keys|touch;try{for(const p of navigator.getGamepads?.()||[]){if(!p)continue;const map={0:14,1:13,2:15,3:12,4:10,5:11,6:8,7:9,12:4,13:6,14:7,15:5};for(const [n,b] of Object.entries(map))if(p.buttons[n]?.pressed)mask|=1<<b;if(p.axes[0]<-.35)mask|=128;if(p.axes[0]>.35)mask|=32;if(p.axes[1]<-.35)mask|=16;if(p.axes[1]>.35)mask|=64;}}catch{}
 if(mask!==last){last=mask;w.postMessage({type:'buttons',mask});}if(t>=next&&ready&&!busy&&!paused&&!document.hidden){busy=true;w.postMessage({type:'tick'});next=Math.max(next+1000/60,t-1000/60);}if(t-next>100)next=t;requestAnimationFrame(tick);}
const keymap={ArrowUp:4,ArrowRight:5,ArrowDown:6,ArrowLeft:7,Space:14,Enter:14,KeyZ:14,KeyX:13,KeyA:15,KeyS:12};
onkeydown=e=>{if(e.target.tagName==='SELECT')return;const b=keymap[e.code];if(b!==undefined){e.preventDefault();keys|=1<<b;}};onkeyup=e=>{const b=keymap[e.code];if(b!==undefined){keys&=~(1<<b);e.preventDefault();}};onblur=()=>{keys=touch=0;};
for(const b of document.querySelectorAll('[data-bit]')){const bit=+b.dataset.bit;b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);touch|=1<<bit;};b.onpointerup=b.onpointercancel=b.onlostpointercapture=()=>{touch&=~(1<<bit);};}
el('game').onchange=()=>{pkg=GAMES[el('game').value];load();};el('restart').onclick=load;el('pause').onclick=()=>{paused=!paused;w.postMessage({type:'pause',paused});el('pause').textContent=paused?'Continuar':'Pausar';if(paused)silence();};
el('sound').onclick=async()=>{try{context??=new(window.AudioContext||window.webkitAudioContext)({sampleRate:48000});await context.resume();sound=!sound;if(!sound)silence();el('sound').textContent=sound?'Silenciar':'Ativar som';}catch(e){el('status').textContent=e.message;}};
el('full').onclick=()=>el('screen').requestFullscreen?.();el('open').onclick=()=>el('input').click();el('input').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>24*1024*1024)throw Error('Limite de 24 MiB.');pkg=JSON.parse(await f.text());load();}catch(error){el('status').textContent=error.message;}finally{e.target.value='';}};
document.addEventListener('visibilitychange',()=>{keys=touch=0;if(document.hidden)silence();});load();requestAnimationFrame(tick);
